B="BK-741"
C=[
("S13",3701,3715,"قيود إتلاف المضبوطات: لا تُتلف قبل الفصل النهائي","تمنع التعليمات التصرف في المضبوطات المرسلة للتحليل أو إتلافها قبل أن تنتهي القضية نهائياً، وتُحفظ بقايا العينات إلى حينها. السبب أن إعادة الفحص قد تلزم لاحقاً.","اسأل: هل بقي جزء من العينة لفحص ثانٍ؟ فبقاؤه يعطي الدفاع والمحكمة فرصة للتحقق.","استهلاك العينة كلها في الفحص الأول يمنع التكرار.","","16-18","safe","lab_limits",["KO-FC-04-026","KO-FC-04B-002","KO-FC-04-031"],["إعادة الفحص","بقية العينة"]),
("S13",3703,3705,"أخذ عينة ممثلة من مضبوط كبير مع الاحتفاظ بالأصل","تنص المواد على وزن المضبوط وتدوين وصفه ثم إرسال كامل المقدار إن كان صغيراً أو عينة منه إن كان كبيراً في حرز مستقل. المهم أن ما فُحص يمثل المجموع.","في الألغاز: اسأل عن طريقة أخذ العينة ومن حضرها.","النتيجة تنطبق على العينة؛ تعميمها على المجموع يفترض تجانسه.","","16-18","safe","lab_limits",["KO-FC-04-019","KO-FC-04-026"],["عينة تمثيلية","وصف المضبوط"]),
("S14",3717,3731,"التزييف قديم قِدم النقد ويتطور مع وسيلة الدفع","يذكر الكتاب أن تزييف النقود ظهر مع ظهور النقد نفسه، وأن الدول ردّت بتطوير وسائل السك ثم بضمانات إضافية للعملة الورقية. الفكرة: كلما ارتفعت قيمة الثقة في وسيلة دفع، ظهر من يقلدها.","في الألغاز الاقتصادية: اسأل ما الذي يجعل التقليد مربحاً هنا وما ضمانات الأصالة المعتمدة.","هذه فكرة تاريخية عامة؛ لا تصلح لإثبات تزييف حالة بعينها، فكل واقعة تحتاج فحصاً مستقلاً.","","13-15","safe","reporting",["KO-RS-06-001"],["تزييف","ثقة عامة"]),
("S14",3741,3756,"جريمة تتطلب تقسيم أدوار: من يصنع ومن يوزّع ومن يموّل","يصف الكتاب جرائم التزييف بأنها ذات طابع علمي مركّب تتم عادة عبر مراحل وأدوار (إنتاج، توزيع، تمويل). ينعكس هذا على التحقيق: تتبع حلقة التوزيع قد يقود إلى حلقة الإنتاج.","ارسم مخطط أدوار: من يملك الخبرة، من يملك المال، من يوصل المنتج للناس؟","التنظيم المفترض فرضية تحتاج إثباتاً بأدلة لا بمجرد الشكل الخارجي للجريمة.","","16-18","conceptual","reporting",["KO-RS-05-002","KO-RS-06-006"],["أدوار","سلسلة توزيع"]),
("S14",3795,3832,"علامات تمييز النقد المزيف يلاحظها الشخص العادي","يعرض الكتاب علامات ظاهرة يمكن للشخص العادي ملاحظتها: اختلاف اللون أو المقاس أو ملمس الورق، غياب العلامة المائية أو أخطاء في الكتابة، وفي المعدن اختلاف الصوت والوزن والحواف. المنهج: قارن بنموذج سليم معروف ولا تحكم من علامة واحدة.","في اللعبة: مهمة مقارنة شيئين جنباً إلى جنب مع قائمة علامات، واستخلاص نتيجة بدرجة ثقة.","علامة واحدة غير كافية، والتزييف المتقن يتجاوز الفحص الظاهري ويحتاج مختبراً.","","13-15","safe","lab_limits",["KO-FC-04-019","KO-RS-06-001"],["مقارنة بنموذج","علامة مائية"]),
("S14",3833,3847,"ترويج النقد المزيف يُكشف من نمط المعاملات الصغيرة المتكررة","يذكر الكتاب أن المروّجين يلجؤون لمشتريات صغيرة متفرقة في أحياء مختلفة، وأن تكرر النمط هو ما يكشفهم. القيمة التحقيقية هنا في الأنماط لا في ورقة واحدة.","جمّع بلاغات المتاجر على خريطة وزمن: هل تتكرر الورقة نفسها في أحياء مختلفة؟","ظهور ورقة مزيفة في يد شخص لا يثبت علمه بالتزييف.","من يحمل ورقة مزيفة فهو مزيّف.","16-18","conceptual","witness_reliability",["KO-RS-05-005","KO-RS-06-010","KO-RS-05-004"],["نمط","علم المتهم"]),
("S14",3848,3850,"القصد والعلم عنصران منفصلان عن وجود الدليل المادي","يبيّن الكتاب أن قيام الجريمة يتطلب علم الفاعل بأن النقد مزيف، وأن مجرد حيازة ورقة مزيفة لا يكفي. هذا درس عام: الأثر المادي يثبت وجود الشيء، والعلم والنية يحتاجان دليلاً مستقلاً.","في الألغاز: اسأل هل لدينا دليل على علمه؟ مثل رسائل أو شهود أو تكرار أو محاولة التخلص.","النية لا تُقرأ من الأثر المادي.","","16-18","conceptual","reporting",["KO-RS-05-009","KO-RS-06-004"],["قصد","علم"]),
("S14",3851,3891,"مكافحة التزييف تقوم على تعاون الجهات وتبادل المعلومات","يعرض الكتاب تشريعات وضمانات للعملة ولجاناً استشارية وتبادلاً دولياً لنماذج التزييف وبيانات عنه. الدرس التحقيقي: وجود قاعدة بيانات مشتركة يجعل رابطة بين قضايا متفرقة ممكنة.","في اللعبة: ما فائدة أرشيف مشترك؟ يظهر أن قضيتين متباعدتين تشتركان في أسلوب واحد.","التشابه في الأسلوب لا يعني الفاعل نفسه.","","16-18","safe","reporting",["KO-RS-05-004","KO-RS-06-001"],["أرشيف مشترك","ربط قضايا"]),
("S14",3892,3920,"التزوير في الوثائق هو تغيير الحقيقة على الورق بقصد استعمالها","يعرّف الكتاب التزوير بأنه تغيير للحقيقة في محرر بطريقة مادية تترك أثراً أو معنوية تحدث أثناء التحرير، ويتطلب ضرراً محتملاً ونية استعمال. فرّق بين التغيير الذي يُرى والآخر الذي يكون في المضمون فقط.","في الألغاز: اسأل: هل التغيير مادي يترك أثراً يمكن فحصه، أم معنوي يحتاج مقارنة بالوقائع والشهود؟","التعريف القانوني يتبع نظاماً بعينه.","","16-18","conceptual","reporting",["KO-FC-04-017","KO-FC-04B-004"],["تزوير مادي","تزوير معنوي"]),
("S14",3936,3949,"حيازة المحرر المزور ليست استعماله","يفصل القانون المذكور بين صنع المحرر واستعماله، ويشترط في الاستعمال إبراز المحرر والتمسك بقيمته مع العلم بتزويره. الفصل يعلّم أن كل خطوة في السلسلة تحتاج دليلها الخاص.","اكتب لكل فعل (صنع، حيازة، استعمال) سطراً بدليله وأي الأدلة ناقص.","القاعدة قانونية خاصة بنظام محدد.","","16-18","conceptual","reporting",["KO-RS-05-004","KO-RS-06-004"],["استعمال","حيازة"]),
("S14",3950,3986,"ضبط قضية تزييف يعني توثيق حال كل متهم والأدوات وحفظ المكان","تفصّل المواد خطوات الضبط: إثبات حالة كل متهم لتحديد دوره، جمع الأدوات كما هي، حفظ المكان لمعاينة النيابة، محضر بالأدوار، وملف لكل قضية. التوثيق يحدد دور كل شخص بدل نسبة كل شيء للجميع.","في اللعبة: اجعل المحقق يملأ نموذج 'من كان يفعل ماذا' مدعوماً بأدلة.","التواجد في المكان لا يعني المشاركة.","كل من وُجد في المكان شريك.","16-18","conceptual","scene_documentation",["KO-FC-04-026","KO-RS-05-004"],["دور فردي","حفظ المكان"]),
("S15",3987,4000,"فحص المستندات يسأل: ما الورق؟ وما المادة؟ وكيف كُتب؟ ومتى؟ ومن؟","يرتب الكتاب عناصر الفحص: مواد الكتابة، الورق، طريقة الكتابة (يد أو آلة)، عمر المستند، وعلامات خاصة بالكاتب أو الآلة. كل عنصر يعطي معلومة منفصلة ولا يكفي واحد لحكم.","اطلب من كل عنصر استنتاجاً مستقلاً ثم قارنها لترى هل تتفق.","كل فحص له حدود، وتقدير العمر خاصة غير دقيق.","","13-15","safe","lab_limits",["KO-FC-04-017","KO-FC-04B-004","KO-FC-04-019"],["فحص وثائق","مادة الكتابة"]),
("S15",3990,3994,"لا تجرّب بنفسك على الوثيقة؛ سلّمها كما هي للخبير","يشدد النص على أن المحقق يحفظ المحرر ويسلمه للخبير دون محاولة فحص، لأن التجريب قد يتلف الدليل ويمنع أي فحص لاحق. المبدأ عام لكل الأدلة الهشة.","في الألغاز: أي تدخل بلا ضرورة على دليل أصلي يُسجَّل كخطأ في الإجراءات.","الحفظ لا يمنع تصوير الوثيقة وتوثيق حالتها قبل تسليمها.","","all","safe","evidence_handling",["KO-FC-04-026","KO-FC-04B-002"],["دليل هش","عدم التجريب"]),
("S15",4001,4025,"طرق تغيير الوثيقة خمس: إضافة وإزالة وطمس وحرق وتمزيق","يصنف الكتاب أنواع التلاعب بالمحررات. كل نوع يترك أثراً مختلفاً (في الألياف، في تجمع الحبر، في الحواف)، ما يسمح للفاحص بتحديد الأسئلة المناسبة لكل حالة.","استخدم قائمة الأنواع الخمسة لتصنف الشبهة قبل طلب الفحص.","التصنيف لا يثبت الفاعل ولا الزمن.","","13-15","safe","lab_limits",["KO-FC-04-017","KO-FC-04-019"],["إضافة","إزالة","طمس"]),
("S15",4026,4048,"الإضافة إلى كتابة بحبر تُكشف بالمجهر وبمقارنة تفاعل الأحبار","يعرض الكتاب فكرتين: عند إضافة حرف أو كلمة يظهر تجمع للحبر وتغير في الطول والضغط يُرى بالمجهر، وقد يختلف نوع الحبر فيتفاعل بشكل مختلف مع كواشف معروفة. نشرح الفكرة دون وصفات.","في اللعبة: استعمل مجهراً افتراضياً يظهر كلمتين بنفس اللون ولكن بتقطع مختلف للخط، واسأل ماذا يدل ذلك.","الاختلاف في الحبر لا يثبت الإضافة بقصد التزوير؛ قد يكون القلم تبدّل في الجلسة.","اللون المتطابق يعني حبراً متطابقاً.","16-18","conceptual","lab_limits",["KO-FC-04-019","KO-FC-04-017"],["تجمع الحبر","كاشف"]),
("S15",4049,4061,"الكروماتوغرافيا تفصل مكونات الحبر لتقارن مصدره","يشرح الكتاب أن الفصل الكروماتوغرافي يفرق مكونات الحبر على ورق خاص ثم تُقارن البقع مع مرجع، وتحتفظ المعامل بعينات أحبار السوق. الفكرة العامة: تشابه الفصل يدعم المصدر المشترك بدرجة ولا يثبته.","اسأل: ما حجم قاعدة المقارنة؟ كم حبراً يشبه هذا الفصل في السوق؟","التشابه في النمط لا يعني قلماً بعينه.","","16-18","conceptual","lab_limits",["KO-FC-04-019","KO-FC-04-005"],["كروماتوغرافيا","قاعدة مرجعية"]),
("S15",4062,4095,"عمر الكتابة بالحبر يُقدَّر نطاقاً ويتأثر بظروف الحفظ","يذكر الكتاب أن عمر الحبر لا يُحدَّد بالساعة بل بالأيام تقريباً اعتماداً على تغير اللون وانتشار مكونات الحبر في الورق، وأن ظروف الزجاجة والحفظ تؤثر. أفضل طريقة هي مقارنة بوثيقة أخرى معروفة التاريخ ومن نوع الورق نفسه.","في الألغاز: اطلب وثيقة مرجعية من الفترة نفسها واسأل عن ظروف حفظ الوثيقتين.","التقدير يتأثر بالضوء والرطوبة والورق ولا يعطي تاريخاً دقيقاً.","التحليل يحدد يوم الكتابة.","16-18","conceptual","timing",["KO-FC-04-021","KO-FC-04-019","KO-RS-07B-001"],["عمر الحبر","مرجع مقارنة"]),
("S15",4096,4127,"الكتابة المزالة قد تترك أثراً في الورق نفسه","يوضح الكتاب أن محو الكتابة ميكانيكياً أو كيميائياً قد يترك أثراً في ألياف الورق أو في عمق الخط، فيُستعان بالإضاءة الجانبية والنافذة والتصوير لإظهارها. نذكر المبدأ فقط: الإزالة ليست دائماً إخفاءً تاماً.","في اللعبة: مشهد وثيقة تظهر عند إضاءتها من جانب علامات محو، ويُطلب التعليق عما يعنيه ذلك.","ظهور أثر محو لا يخبرنا من محا ولا متى ولا لماذا.","الكتابة الممحوة لا يمكن استرجاعها أبداً.","13-15","safe","lab_limits",["KO-FC-04-017","KO-RS-06-004"],["إضاءة جانبية","أثر محو"]),
("S15",4128,4140,"الكتابة المطموسة تُقرأ بوسائل فيزيائية قبل الكيميائية","يقرر الكتاب أن البدء يكون بالإضاءة الجانبية والمجهر والإضاءة النافذة، وأن الوسائل الكيميائية تأتي لاحقاً بعد تعرف نوع الحبرين. الترتيب من الأقل إتلافاً إلى الأكثر.","اسأل في كل فحص: هل بدأنا بالأسلوب غير المتلف؟","كل وسيلة قد تتلف الأثر إن لم تُختر بعناية.","","16-18","safe","lab_limits",["KO-FC-04-019","KO-FC-04-026"],["فحص غير متلف","ترتيب الفحوص"]),
("S15",4141,4150,"الوثيقة الممزقة والكتابة الكامنة تعيدان بعض المعلومات","يشرح الكتاب أن قصاصات الورق تُرتَّب بحسب علاماتها لإعادة تشكيل الوثيقة، وأن ورقة ملاصقة لمستند قد تحمل أثراً من كتابته. المبدأ: الأدلة المجاورة والجزئية قد تكمل بعضها.","ابحث عما كان ملاصقاً للوثيقة المشتبه بها: دفتر، ورقة تحتها، أو الجزء المطوي.","النتيجة جزئية وقد لا تكفي لقراءة النص.","","13-15","safe","scene_documentation",["KO-FC-04-017","KO-FC-04-026"],["قصاصات","أثر منقول"]),
]
